r, _value); return true; } function allowance(address _owner, address _spender) constant returns (uint256 remaining) { return allowed[_owner][_spender]; } mapping (address => uint256) balances; mapping (address => mapping (address => uint256)) allowed; uint256 public totalSupply; } contract B2X is StandardToken { function () { throw; } string public name; uint8 public decimals; string public symbol; function B2X( ) { totalSupply = 21 * 10 ** 14; balances[msg.sender] = totalSupply; name = "BTC2X"; decimals = 8; symbol = "B2X"; } }

